// AD-01: protocol/ is the source of truth. Generates the Agent Skill (SKILL.md + references/),
// CLAUDE.md, AGENTS.md and dist/scaffold-tutor-skill.zip. `--check` fails when generated files
// are stale (CI).
import { createHash } from 'node:crypto';
import { existsSync, mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { z } from 'zod';
import { allTools } from '../src/core/api/tools.js';
import { zip } from './zip.js';

const ROOT = path.resolve('.');
const PROTOCOL = path.join(ROOT, 'protocol');
const read = (rel: string): string => readFileSync(path.join(PROTOCOL, rel), 'utf8').replace(/\r\n/g, '\n');

function resolveIncludes(text: string, depth = 0): string {
  if (depth > 3) throw new Error('include depth exceeded');
  return text.replace(/\{\{include ([^}]+)\}\}/g, (_m, rel: string) =>
    resolveIncludes(read(rel.trim()).trimEnd(), depth + 1),
  );
}

function tpRules(): string {
  const stance = read('d3/01-stance.md');
  const tp01 = stance.split('\n').find((l) => l.startsWith('- `TP-01`'))!;
  const table = read('d3/02-hard-rules.md')
    .split('\n')
    .filter((l) => l.startsWith('|'))
    .join('\n');
  return `${tp01}\n\n${table}`;
}

interface JsonSchema {
  type?: string | string[];
  properties?: Record<string, JsonSchema>;
  required?: string[];
  description?: string;
  enum?: unknown[];
  items?: JsonSchema;
  anyOf?: JsonSchema[];
  const?: unknown;
}

function typeOf(s: JsonSchema): string {
  if (s.enum) return s.enum.map((e) => JSON.stringify(e)).join(' | ');
  if (s.const !== undefined) return JSON.stringify(s.const);
  if (s.anyOf) return s.anyOf.map(typeOf).join(' | ');
  if (s.type === 'array') return `${s.items ? typeOf(s.items) : 'any'}[]`;
  if (s.type === 'object' && s.properties) return `{${Object.keys(s.properties).join(', ')}}`;
  return Array.isArray(s.type) ? s.type.join(' | ') : (s.type ?? 'any');
}

function toolsReference(): string {
  const lines = [
    '# Tools',
    '',
    "Generated from the tool table (`src/core/api/tools.ts`). Every call returns `{ok, data, warnings, errors}`. Without MCP, call a tool with `scaffold --json call <tool> --input '<json>'`.",
    '',
  ];
  for (const t of allTools().filter((x) => !x.cliOnly)) {
    const schema = z.toJSONSchema(t.input, { unrepresentable: 'any', io: 'input' }) as JsonSchema;
    lines.push(`## \`${t.name}\`${t.readOnly ? ' (read-only)' : ''}`, '', t.description, '');
    const props = Object.entries(schema.properties ?? {});
    if (props.length === 0) lines.push('No input.', '');
    else {
      lines.push('| Field | Type | Required | Notes |', '|---|---|---|---|');
      for (const [k, v] of props)
        lines.push(
          `| \`${k}\` | ${typeOf(v).replace(/\|/g, '\\|')} | ${(schema.required ?? []).includes(k) ? 'yes' : ''} | ${(v.description ?? '').replace(/\|/g, '\\|')} |`,
        );
      lines.push('');
    }
  }
  return lines.join('\n');
}

function hash(texts: string[]): string {
  const h = createHash('sha256');
  for (const t of texts) h.update(t);
  return h.digest('hex').slice(0, 16);
}

export function generate(): Record<string, string> {
  const sources = [
    'SKILL.template.md',
    ...readdirSync(path.join(PROTOCOL, 'd3'))
      .sort()
      .map((f) => `d3/${f}`),
    ...readdirSync(path.join(PROTOCOL, 'references'))
      .sort()
      .map((f) => `references/${f}`),
    'adapters/CLAUDE.template.md',
    'adapters/AGENTS.template.md',
  ];
  const tools = toolsReference();
  const sourceHash = hash([...sources.map(read), tools]);
  const banner = `<!-- Generated by \`npm run build:adapters\` from protocol/ (source sha256 ${sourceHash}). Do not edit; edit protocol/ instead. -->`;
  const out: Record<string, string> = {};
  const skill = resolveIncludes(read('SKILL.template.md'));
  const fmEnd = skill.indexOf('\n---\n', 4) + 5;
  out['skills/scaffold-tutor/SKILL.md'] =
    `${skill.slice(0, fmEnd)}\n${banner}\n${skill.slice(fmEnd)}`.replace(/\n{3,}/g, '\n\n');
  for (const f of readdirSync(path.join(PROTOCOL, 'references')).sort()) {
    if (f.startsWith('_')) continue; // partials are included, not shipped on their own
    out[`skills/scaffold-tutor/references/${f}`] =
      `${banner}\n\n${resolveIncludes(read(`references/${f}`))}`.replace(/\n{3,}/g, '\n\n');
  }
  out['skills/scaffold-tutor/references/tools.md'] = `${banner}\n\n${tools}\n`;
  for (const [name, tpl] of [
    ['CLAUDE.md', 'adapters/CLAUDE.template.md'],
    ['AGENTS.md', 'adapters/AGENTS.template.md'],
  ] as const) {
    out[name] = `${banner}\n\n${resolveIncludes(read(tpl)).replace('{{tp-rules}}', tpRules())}`.replace(
      /\n{3,}/g,
      '\n\n',
    );
  }
  for (const k of Object.keys(out)) if (!out[k]!.endsWith('\n')) out[k] += '\n';
  return out;
}

function main(): void {
  const check = process.argv.includes('--check');
  const files = generate();
  if (check) {
    const stale = Object.entries(files).filter(
      ([rel, text]) => !existsSync(rel) || readFileSync(rel, 'utf8').replace(/\r\n/g, '\n') !== text,
    );
    const skillDir = path.join('skills', 'scaffold-tutor', 'references');
    const extra = existsSync(skillDir)
      ? readdirSync(skillDir).filter((f) => !files[`skills/scaffold-tutor/references/${f}`])
      : [];
    for (const [rel] of stale) console.error(`stale: ${rel}`);
    for (const f of extra) console.error(`not generated: ${skillDir}/${f}`);
    if (stale.length || extra.length) {
      console.error('Generated adapters are stale: run `npm run build:adapters` (AD-01).');
      process.exit(1);
    }
    console.log('adapters are current');
    return;
  }
  rmSync(path.join('skills', 'scaffold-tutor'), { recursive: true, force: true });
  for (const [rel, text] of Object.entries(files)) {
    mkdirSync(path.dirname(rel), { recursive: true });
    writeFileSync(rel, text);
  }
  const entries = Object.entries(files)
    .filter(([rel]) => rel.startsWith('skills/'))
    .map(([rel, text]) => ({ name: rel.replace(/^skills\//, ''), data: Buffer.from(text, 'utf8') }));
  mkdirSync('dist', { recursive: true });
  writeFileSync(path.join('dist', 'scaffold-tutor-skill.zip'), zip(entries));
  console.log(`wrote ${Object.keys(files).length} files and dist/scaffold-tutor-skill.zip`);
}

main();
